/* Bare portal layout helpers (shared shell paint lives in lux-tokens / lux-shell).
 * No shared-shell-chrome / shared-surface / shared-actions selectors — those live in lux-shell.css.
 */
body.lux-page-bare main, body.lux-page-bare .lux-page-shell, body.lux-page-bare #page-content {
  min-width: 0;
}
body.lux-page-bare .lux-page-shell { display: grid; gap: 12px; padding: 12px 0; }
body.lux-page-bare .lux-page-title, body.lux-page-bare h1 {
  color: var(--lux-text, #f8fafc);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin: 0;
}
body.lux-page-bare .lux-page-copy, body.lux-page-bare .lux-page-kicker {
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  line-height: 1.5;
  margin: 0;
}
body.lux-page-bare .lux-field-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }
body.lux-page-bare .lux-field { display: grid; gap: 6px; min-width: 0; }
body.lux-page-bare .lux-field label, body.lux-page-bare .lux-overline {
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
body.lux-page-bare .lux-subcards, body.lux-page-bare .lux-strip-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 10px;
}
body.lux-page-bare .lux-pill-row, body.lux-page-bare .lux-card-actions, body.lux-page-bare .lux-actions-between {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
body.lux-page-bare table { width: 100%; border-collapse: collapse; }
body.lux-page-bare table th, body.lux-page-bare table td {
  padding: 8px 10px;
  border-bottom: 1px solid var(--lux-border, rgba(255, 255, 255, 0.08));
  text-align: left;
  vertical-align: top;
}
body.lux-page-bare table thead th {
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
body.lux-page-bare .lux-queue-list, body.lux-page-bare .lux-thread { display: grid; gap: 8px; }
@media (max-width: 920px) {
  body.lux-page-bare .lux-field-grid { grid-template-columns: 1fr; }
}

/* ── Bare host contract (paint → lux-fouc-ht / lux-controls) ── */

body.lux-unified-shell.lux-page-bare {
  font-family: 'Manrope', 'Inter', system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* Layout-only shells: spacing wrapper — real glass hosts use data-lux-glass-root="1" */
body.lux-page-bare .lux-page-shell[data-lux-layout-only="1"] {
  background: transparent;
  border: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

/* Section hosts: spacing only (outer paint → FOUC panel SSOT). */
#lux-admin-tools-shell .lux-panel {
  padding: 24px;
  margin-bottom: 20px;
}
#page-programs .lux-panel.lux-program-command-deck {
  padding: clamp(16px, 2vw, 24px);
  margin-bottom: 0;
}

/* Head titles and kickers */
#lux-admin-tools-shell .lux-card-title,
#lux-admin-tools-shell .admin-reg-program-head-title {
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--lux-text, #f8fafc);
  letter-spacing: -0.015em;
}
#lux-admin-tools-shell .lux-section-kicker {
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
}
body.lux-route-programs #page-programs .lux-section-kicker {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Ops panel spacing and grid — tiles use shared .lux-stat.lux-soft-chrome */
#lux-admin-tools-shell .lux-admin-curriculum-ops-panel,
body.lux-route-programs #page-programs .lux-prog-ops-panel {
  margin: 0 0 14px;
}
#lux-admin-tools-shell .lux-admin-curriculum-ops-grid,
body.lux-route-programs #page-programs .lux-prog-ops-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 10px;
}
#lux-admin-tools-shell .lux-admin-curriculum-ops-grid .lux-stat em,
body.lux-route-programs #page-programs .lux-prog-ops-grid .lux-stat em {
  font-size: 11px;
  font-style: normal;
  font-weight: 600;
}

/* Control band layout */
#lux-admin-tools-shell .lux-admin-curriculum-control-band,
body.lux-route-programs #page-programs .lux-prog-control-band {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
  margin: 0 0 14px;
  padding: 12px 14px;
}
#lux-admin-tools-shell .lux-admin-curriculum-control-band .lux-program-field,
body.lux-route-programs #page-programs .lux-prog-control-band .lux-program-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 200px;
  min-width: 180px;
}
#lux-admin-tools-shell .lux-admin-curriculum-control-band .lux-program-field > span,
#lux-admin-tools-shell .lux-admin-curriculum-control-band .lux-program-field > .lux-picker-label,
body.lux-route-programs #page-programs .lux-prog-control-band .lux-program-field > span,
body.lux-route-programs #page-programs .lux-prog-control-band .lux-program-field > .lux-picker-label {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
}

/* Search icon layout; field paint comes from shared .lux-control. */
#lux-admin-tools-shell .lux-admin-curriculum-search-wrap,
body.lux-route-programs #page-programs .lux-program-search-wrap {
  position: relative;
}
#lux-admin-tools-shell .lux-admin-curriculum-search-wrap > i,
body.lux-route-programs #page-programs .lux-program-search-wrap > i {
  position: absolute;
  left: 12px;
  bottom: calc(var(--lux-field-min-height, 44px) / 2);
  transform: translateY(50%);
  z-index: 1;
  pointer-events: none;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.55));
  font-size: 13px;
}
#lux-admin-tools-shell #admin-curriculum-search,
body.lux-route-programs #page-programs #student-program-search {
  padding-left: 36px;
  padding-right: 44px;
}
body.lux-route-programs #page-programs .lux-program-clear-search {
  position: absolute;
  right: 6px;
  bottom: calc(var(--lux-field-min-height, 44px) / 2);
  transform: translateY(50%);
  z-index: 1;
  min-width: 32px;
  min-height: 32px;
  padding: 0;
}

/* Curriculum / program 2-column grids */
#lux-admin-tools-shell .lux-admin-curriculum-grid,
#lux-admin-tools-shell .lux-program-grid,
#page-programs .lux-program-grid {
  display: grid;
  grid-template-columns: minmax(280px, 360px) minmax(0, 1fr);
  gap: 14px;
  align-items: start;
}
#lux-admin-tools-shell .lux-section-card,
#page-programs .lux-section-card {
  padding: 16px;
}

/* Registration tab container */
#lux-admin-tools-shell .lux-admin-tools-reg-tabs {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  margin: 0 0 12px;
}
#lux-admin-tools-shell .admin-reg-tab-tray {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}
/* Curriculum / registration head rows */
#lux-admin-tools-shell :is(.curriculum-library-head, .curriculum-library-detail-head),
body.lux-route-programs #page-programs :is(.lux-program-section-head, .lux-program-detail-head) {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
#lux-admin-tools-shell .curriculum-library-detail-head,
body.lux-route-programs #page-programs .lux-program-detail-head {
  align-items: flex-start;
}
#lux-admin-tools-shell .lux-card-head.lux-admin-tools-registration-panel-head {
  display: flex;
  flex-direction: row;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: nowrap;
  gap: 12px;
  margin-bottom: 16px;
}
#lux-admin-tools-shell .lux-admin-tools-registration-head-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

/* Registration program workspace */
#lux-admin-tools-shell .admin-reg-program-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
#lux-admin-tools-shell .admin-reg-program-layout {
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: 20px;
  align-items: start;
}
#lux-admin-tools-shell .admin-reg-program-layout--wide {
  grid-template-columns: 320px minmax(0, 1fr);
  gap: 18px;
}
#lux-admin-tools-shell .admin-reg-program-list-shell {
  padding: 16px;
}
#lux-admin-tools-shell .admin-reg-program-list-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
}
#lux-admin-tools-shell .admin-reg-program-list-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
}
#lux-admin-tools-shell .admin-reg-program-list-count {
  font-size: 11px;
  color: var(--lux-accent, #0b84ff);
  font-weight: 800;
}
#lux-admin-tools-shell .admin-reg-program-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  max-height: min(60vh, 480px);
  overflow: auto;
  padding-right: 4px;
}
#lux-admin-tools-shell .admin-reg-program-list-title--strong {
  font-size: 13px;
  font-weight: 800;
}
#lux-admin-tools-shell .admin-reg-program-list-empty {
  padding: 24px 12px;
  text-align: center;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
}
#lux-admin-tools-shell .admin-reg-program-list-placeholder {
  padding: 20px;
  text-align: center;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  border: 1px dashed var(--lux-panel-border-soft, rgba(255, 255, 255, 0.12));
  border-radius: 12px;
  background: var(--lux-panel-surface-soft, rgba(15, 23, 42, 0.35));
}

/* Program list options */
#lux-admin-tools-shell .admin-reg-program-option {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 10px 12px;
  border: 1px solid var(--lux-panel-border-soft, rgba(255, 255, 255, 0.12));
  border-radius: 10px;
  background: transparent;
  cursor: pointer;
  transition: border-color 150ms ease, background 150ms ease, box-shadow 150ms ease;
}
#lux-admin-tools-shell .admin-reg-program-option--wide {
  flex-direction: row;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
#lux-admin-tools-shell .admin-reg-program-option:hover,
#lux-admin-tools-shell .admin-reg-program-option:focus-within {
  border-color: rgba(var(--lux-accent-rgb, 11, 132, 255), 0.2);
}
#lux-admin-tools-shell .admin-reg-program-option.is-active {
  background: rgba(var(--lux-accent-rgb, 11, 132, 255), 0.08);
  border-color: rgba(var(--lux-accent-rgb, 11, 132, 255), 0.24);
  box-shadow: inset 3px 0 0 var(--lux-accent, #0b84ff);
}
#lux-admin-tools-shell .admin-reg-program-option-label {
  display: block;
  flex: 1;
  min-width: 0;
  cursor: pointer;
}
#lux-admin-tools-shell .admin-reg-program-option-row {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}
#lux-admin-tools-shell .admin-reg-program-option-input {
  margin: 0;
  accent-color: var(--lux-accent, #0b84ff);
  inline-size: 16px;
  block-size: 16px;
  flex: 0 0 auto;
}
#lux-admin-tools-shell .admin-reg-program-option-title {
  font-weight: 700;
  color: var(--lux-text, #f8fafc);
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#lux-admin-tools-shell .admin-reg-program-option-progress {
  font-size: 10px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  padding-left: 26px;
}
#lux-admin-tools-shell .admin-reg-program-option-progress--pill {
  padding-left: 0;
  font-size: 11px;
  font-weight: 800;
  color: var(--lux-accent, #0b84ff);
  background: color-mix(in srgb, var(--lux-accent, #0b84ff) 12%, transparent);
  border: 1px solid rgba(var(--lux-accent-rgb, 11, 132, 255), 0.16);
  padding: 5px 8px;
  border-radius: 999px;
  white-space: nowrap;
}
#lux-admin-tools-shell .admin-reg-program-option-actions {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
}

/* Program pane (free / prog CMS layouts) */
#lux-admin-tools-shell .admin-reg-program-pane-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 16px;
}
#lux-admin-tools-shell .admin-reg-program-pane-main {
  min-width: 0;
}
#lux-admin-tools-shell .admin-reg-program-pane-title {
  font-size: 15px;
  font-weight: 700;
  color: var(--lux-text, #f8fafc);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#lux-admin-tools-shell .admin-reg-program-pane-copy {
  font-size: 11px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  margin-top: 3px;
}
#lux-admin-tools-shell .admin-reg-program-pane-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
  align-items: center;
}
#lux-admin-tools-shell .admin-reg-program-pane-progress {
  font-size: 11px;
  font-weight: 800;
  color: var(--lux-accent, #0b84ff);
  background: color-mix(in srgb, var(--lux-accent, #0b84ff) 12%, transparent);
  border: 1px solid rgba(var(--lux-accent-rgb, 11, 132, 255), 0.16);
  padding: 5px 10px;
  border-radius: 999px;
  white-space: nowrap;
}
#lux-admin-tools-shell .admin-reg-program-pane-btn {
  padding: 7px 12px;
  font-size: 11px;
}
#lux-admin-tools-shell .admin-reg-program-pane-btn--primary {
  padding: 8px 14px;
  font-size: 12px;
}
#lux-admin-tools-shell .admin-reg-program-subject-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
#lux-admin-tools-shell .admin-reg-program-subject-head {
  display: flex;
  gap: 8px;
  margin-top: 12px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}
#lux-admin-tools-shell .admin-reg-program-subject-head-number { width: 84px; text-align: center; }
#lux-admin-tools-shell .admin-reg-program-subject-head-title { flex: 3; }
#lux-admin-tools-shell .admin-reg-program-subject-head-ects { width: 110px; text-align: center; }
#lux-admin-tools-shell .admin-reg-program-subject-head-meta { flex: 2; }
#lux-admin-tools-shell .admin-reg-program-subject-head-actions { width: 120px; }
#lux-admin-tools-shell .admin-reg-program-subject-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border: 1px solid var(--lux-panel-border-soft, rgba(255, 255, 255, 0.12));
  border-radius: 12px;
  background: var(--lux-panel-surface-soft, rgba(15, 23, 42, 0.35));
