}
#lux-admin-tools-shell .admin-reg-program-subject-number {
  width: 84px;
  text-align: center;
  font-weight: 800;
  color: var(--lux-accent-2, #38bdf8);
}
#lux-admin-tools-shell .admin-reg-program-subject-main { flex: 3; min-width: 0; }
#lux-admin-tools-shell .admin-reg-program-subject-title {
  font-weight: 700;
  color: var(--lux-text, #f8fafc);
}
#lux-admin-tools-shell .admin-reg-program-subject-courses {
  font-size: 10px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  margin-top: 2px;
}
#lux-admin-tools-shell .admin-reg-program-subject-ects {
  width: 110px;
  text-align: center;
  font-weight: 800;
  color: var(--lux-accent-2, #38bdf8);
}
#lux-admin-tools-shell .admin-reg-program-subject-details {
  flex: 2;
  font-size: 11px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
}
#lux-admin-tools-shell .admin-reg-program-subject-detail { margin-top: 4px; }
#lux-admin-tools-shell .admin-reg-program-subject-detail--semester {
  color: var(--lux-green, #22c55e);
  font-weight: 700;
}
#lux-admin-tools-shell .admin-reg-program-subject-detail--access {
  color: var(--lux-accent-2, #38bdf8);
  font-weight: 700;
}
#lux-admin-tools-shell .admin-reg-program-subject-actions {
