#lux-admin-tools-shell .admin-reg-track-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 18px;
}
#lux-admin-tools-shell .admin-reg-track-head-title {
  font-size: 20px;
  font-weight: 800;
  color: var(--lux-text, #f8fafc);
}
#lux-admin-tools-shell .admin-reg-track-head-copy {
  margin-top: 4px;
  font-size: 13px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
}
#lux-admin-tools-shell .admin-reg-track-groups {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
#lux-admin-tools-shell .admin-reg-track-group-card {
  border: 1px solid var(--lux-panel-border-soft, rgba(255, 255, 255, 0.12));
  border-radius: 12px;
  background: var(--lux-panel-surface-soft, rgba(15, 23, 42, 0.35));
  box-shadow: var(--lux-soft-chrome-surface-shadow, none);
