}
#lux-admin-tools-shell .admin-reg-track-group-copy {
  margin-top: 3px;
  font-size: 11px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
}
#lux-admin-tools-shell .admin-reg-track-group-progress {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 30px;
  padding: 6px 12px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--lux-accent, #0b84ff) 12%, transparent);
  border: 1px solid rgba(var(--lux-accent-rgb, 11, 132, 255), 0.16);
  color: var(--lux-accent, #0b84ff);
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}
#lux-admin-tools-shell .admin-reg-track-group-header .admin-reg-track-group-actions {
