  padding: 0 18px 18px;
  border-top: 1px solid rgba(var(--lux-accent-rgb, 11, 132, 255), 0.1);
}
#lux-admin-tools-shell .admin-reg-track-subject-head {
  display: grid;
  grid-template-columns: 72px minmax(0, 1.5fr) 96px minmax(0, 1fr) 104px;
  gap: 10px;
  margin-top: 16px;
  margin-bottom: 10px;
  color: var(--lux-text-muted, rgba(248, 250, 252, 0.65));
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}
#lux-admin-tools-shell .admin-reg-track-subject-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
#lux-admin-tools-shell .admin-reg-track-subject-row {
  display: grid;
  grid-template-columns: 72px minmax(0, 1.5fr) 96px minmax(0, 1fr) 104px;
  gap: 10px;
  align-items: center;
  padding: 12px 14px;
