  min-height: 70vh;
}
#portal-news-root .newsx-shell {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  gap: 18px;
  margin-top: 24px;
  align-items: start;
}
#portal-news-root .newsx-sidebar {
  position: sticky;
  top: 18px;
  padding: 20px;
  border-radius: var(--lux-radius, 18px);
}
#portal-news-root .newsx-main {
  display: grid;
  gap: 18px;
  min-width: 0;
}
#portal-news-root .newsx-header-bar,
#portal-news-root .newsx-feed-card.lux-soft-chrome {
  padding: 20px;
  border-radius: var(--lux-radius, 18px);
}
#portal-news-root .newsx-header-bar {
  display: grid;
  gap: 14px;
  background: var(--lux-panel-surface);
  border: 1px solid var(--lux-panel-border);
  box-shadow: var(--lux-panel-shadow);
}
#portal-news-root .newsx-header-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 14px;
  flex-wrap: wrap;
}
#portal-news-root .newsx-hero-command {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}
#portal-news-root .newsx-kicker {
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 11px;
  font-weight: 900;
  opacity: 0.78;
}
#portal-news-root .newsx-kicker-muted { color: var(--lux-text-muted); opacity: 1; }
#portal-news-root .newsx-icon-leading { margin-right: 6px; }
#portal-news-root .newsx-title {
  margin: 10px 0 0;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: clamp(30px, 4.2vw, 44px);
  line-height: 0.98;
  letter-spacing: -0.04em;
  font-weight: 700;
}
#portal-news-root .newsx-headline {
