  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
}
#portal-news-root .newsx-filter-grid--extended {
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
}
#portal-news-root .newsx-filter-meta {
