/* ── Social workspace (#page-social): layout only (paint → lux-tokens / lux-fouc-ht) ── */
body.lux-route-social {
  --social-gap: 16px;
  --social-gap-tight: 10px;
  --social-radius: 20px;
  --social-chip-fill: var(--lux-soft-chrome-control, var(--lux-panel-control, color-mix(in srgb, var(--lux-panel-fill, rgba(12, 18, 28, 0.82)) 72%, transparent)));
  --social-chip-border: var(--lux-soft-chrome-border-accent, var(--lux-panel-border-soft, var(--lux-border)));
  --social-chip-surface: var(--lux-soft-chrome-surface, none);
  --social-fade-row: rgba(var(--lux-glass-tint-rgb, 16, 23, 38), calc(var(--lux-raised-fill-alpha, 0.045) + 0.04));
  --social-fade-row-hover: rgba(var(--lux-accent-rgb), calc(0.04 + var(--lux-transparency-alpha, 0.92) * 0.06));
  --social-fade-border-soft: rgba(255, 255, 255, 0.10);
  --social-fade-control: linear-gradient(180deg, rgba(255, 255, 255, calc(0.04 + var(--lux-glass-alpha, .06))), rgba(255, 255, 255, 0.02)), radial-gradient(circle at top right, rgba(var(--lux-accent-rgb), 0.10), transparent 32%);
  --social-msg-stream: transparent;
  --social-msg-bubble-in: rgba(255, 255, 255, .06);
  --social-msg-bubble-own: rgba(var(--sn-accent-rgb, var(--lux-accent-rgb)), .18);
  --social-msg-bubble-border: rgba(255, 255, 255, .08);
  --social-msg-composer: var(--social-fade-control);
  --sn-txt: var(--lux-text, #fbfaf6);
  --sn-txt2: var(--lux-text-muted, rgba(251,250,246,.62));
  --sn-txt3: var(--lux-text-soft, rgba(251,250,246,.34));
  --sn-accent: var(--lux-accent, #c8822a);
  --sn-accent-rgb: var(--lux-accent-rgb, 200,130,42);
  --sn-bdr: var(--social-fade-border-soft);
  --sn-hover: var(--social-fade-row-hover);
  --msg-stream-bg: var(--social-msg-stream);
}

body.lux-route-social:not(.lux-light-mode) {
  color-scheme: dark;
}

body.lux-light-mode.lux-route-social,
html.lux-light-mode body.lux-route-social {
  --social-fade-border-soft: rgba(77, 52, 31, 0.12);
  --social-fade-control: linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(248, 244, 237, 0.86));
  --social-fade-row: rgba(255, 255, 255, 0.68);
  --social-fade-row-hover: rgba(var(--lux-accent-rgb), 0.09);
  --social-msg-stream: rgba(255, 255, 255, 0.36);
  --social-msg-bubble-in: rgba(255, 255, 255, 0.82);
  --social-msg-bubble-own: rgba(var(--lux-accent-rgb), 0.16);
  --social-msg-bubble-border: rgba(77, 52, 31, 0.12);
  --sn-txt: var(--lux-text);
  --sn-txt2: color-mix(in srgb, var(--lux-text) 76%, transparent);
  --sn-txt3: color-mix(in srgb, var(--lux-text) 52%, transparent);
}

