/*
 * Nested frame + connecting lines (├── / └──).
 * Frame = who owns the group. Lines = which rows hang off that parent.
 */
body.lux-route-social .spt-desk--v2 .spt-desk-tree-node {
    display: flex;
    flex-direction: column;
    min-width: 0;
    position: relative;
}
body.lux-route-social .spt-desk--v2 .spt-desk-tree-node > .spt-desk-card.spt-desk-row {
    border-radius: 0;
}

/*
 * Tree lines: paint-only (absolute + background). NEVER box-model border
 * on the connection path — borders open 1px holes between segments.
 * Paper-ledger surfaces: warm elevated frames (not charcoal wells).
 */
body.lux-route-social .spt-desk--v2 {
    /* Follow the active theme accent (teal / orange / whatever the user picks);
     * indigo is only the fallback when no theme token is set. */
    --spt-neutral-rgb: 148, 163, 184; /* structural chrome — stays cool/neutral */
    /* readable light tint of the accent for text on the dark frame */
    --spt-desk-accent-ink: color-mix(in srgb, rgb(var(--lux-accent-rgb, 200, 130, 42)), #ffffff 48%);
    --spt-tree-line: rgba(var(--lux-accent-rgb, 200, 130, 42), 0.55);
    --spt-tree-line-dim: rgba(var(--lux-accent-rgb, 200, 130, 42), 0.4);
    --spt-tree-gutter: 24px;
    --spt-tree-x: 10px;
    --spt-tree-w: 1.5px;
    --spt-tree-r: 11px; /* last-child elbow curve radius */
    /* vertical center of the child card */
    --spt-tree-elbow-y: 27px;
    --spt-tree-gap: 8px;    /* MUST match children flex gap (bridges the joint) */
    --spt-tree-pad-top: 8px; /* MUST match children padding-top (climbs to header) */
    --spt-frame-bg:
        radial-gradient(120% 80% at 0% 0%, rgba(var(--lux-accent-rgb, 200, 130, 42), 0.1), transparent 55%),
        linear-gradient(180deg, rgba(30, 41, 59, 0.55), rgba(15, 23, 42, 0.62));
    --spt-frame-shadow:
        inset 0 0 0 1px rgba(var(--spt-neutral-rgb), 0.16),
        0 14px 34px rgba(2, 6, 23, 0.42),
        inset 0 1px 0 rgba(255, 255, 255, 0.05);
    --spt-frame-head: linear-gradient(180deg, rgba(var(--lux-accent-rgb, 200, 130, 42), 0.08), transparent);
    --spt-frame-head-rule: rgba(var(--spt-neutral-rgb), 0.16);
    --spt-nest-bg: rgba(var(--spt-neutral-rgb), 0.04);
    --spt-nest-2-bg: rgba(var(--spt-neutral-rgb), 0.06);
    --spt-row-child: linear-gradient(180deg, rgba(var(--spt-neutral-rgb), 0.07), rgba(var(--spt-neutral-rgb), 0.03));
    --spt-row-child-hover: linear-gradient(180deg, rgba(var(--lux-accent-rgb, 200, 130, 42), 0.12), rgba(var(--spt-neutral-rgb), 0.05));
    --spt-row-child-edge: rgba(var(--lux-accent-rgb, 200, 130, 42), 0.55);
    --spt-row-child-ring: rgba(var(--spt-neutral-rgb), 0.14);
}


/* Family frame — soft paper well, amber hairline */
body.lux-route-social .spt-desk--v2 .spt-desk-tree-node:has(> .spt-desk-tree-children:not(.is-collapsed)) {
    margin: 12px 12px 16px;
