/* (child rails enabled above — do not hide again) */

/* Nested parent (xcv): transparent shell, zero borders */
body.lux-route-social .spt-desk--v2 .spt-desk-tree-children > .spt-desk-tree-node:has(> .spt-desk-tree-children:not(.is-collapsed)) {
    margin: 0;
    border: 0 !important;
    border-radius: 0;
    background: transparent;
    overflow: visible;
    box-shadow: none;
}
body.lux-route-social .spt-desk--v2 .spt-desk-tree-children > .spt-desk-tree-node:has(> .spt-desk-tree-children:not(.is-collapsed)) > .spt-desk-card.spt-desk-row {
    border: 0 !important;
    background: var(--spt-frame-head);
    box-shadow:
        inset 0 0 0 1px var(--spt-frame-head-rule),
        inset 3px 0 0 var(--spt-tree-line);
}

/* Grandchildren: same flush line system under parent — step surface, not black card */
body.lux-route-social .spt-desk--v2 .spt-desk-tree-children .spt-desk-tree-children {
    --spt-tree-line: var(--spt-tree-line-dim);
    --spt-tree-gap: 6px;
    --spt-tree-pad-top: 6px;
    margin: 0;
