}

body.lux-route-study-card #page-study-card .study-card-summary-focus :is(
    .lux-focus-panel__title,
    .lux-focus-panel__copy
) {
    display: block;
    overflow: visible;
    -webkit-line-clamp: unset;
    overflow-wrap: anywhere;
}

body.lux-route-study-card #page-study-card .study-card-summary-focus .lux-focus-panel__meta > span.lux-hero-signal {
    white-space: normal;
    text-align: left;
    justify-content: flex-start;
    border-radius: 14px;
}

body.lux-route-study-card #page-study-card .lms-route-meta-12 {
    color: var(--lux-text-muted);
}

body.lux-route-study-card #page-study-card .study-card-cell .lms-route-copy {
    margin: 0;
    color: var(--lux-text-muted);
}

body.lux-route-study-card #page-study-card .study-card-heading.lms-route-field-label {
    margin-bottom: 0;
    color: var(--lux-text-muted);
}

body.lux-route-study-card #page-study-card .study-card-cell--ects,
body.lux-route-study-card #page-study-card .study-card-cell--score {
    font-weight: 700;
    color: var(--lux-text);
}

body.lux-light-mode.lux-route-study-card #page-study-card :is(
    .lux-page-title,
    .lms-route-card-title,
    .study-card-cell--ects,
    .study-card-cell--score
),
html.lux-light-mode body.lux-route-study-card #page-study-card :is(
    .lux-page-title,
    .lms-route-card-title,
    .study-card-cell--ects,
    .study-card-cell--score
) {
    color: var(--lux-text);
}

body.lux-light-mode.lux-route-study-card #page-study-card :is(
    .lux-card-copy,
    .lms-route-copy,
    .lms-route-meta-12,
    .study-card-control-label,
    .study-card-heading
),
html.lux-light-mode body.lux-route-study-card #page-study-card :is(
    .lux-card-copy,
    .lms-route-copy,
    .lms-route-meta-12,
    .study-card-control-label,
    .study-card-heading
) {
    color: var(--lux-text-muted, var(--lux-text-secondary));
}

@media (max-width: 900px) {
    body.lux-route-study-card .study-card-summary-stage.lux-hero-stage {
        grid-template-columns: 1fr;
    }

    body.lux-route-study-card .study-card-semester-table,
    body.lux-route-study-card .study-card-semester-table thead,
    body.lux-route-study-card .study-card-semester-table tbody,
    body.lux-route-study-card .study-card-semester-table tr,
    body.lux-route-study-card .study-card-semester-table td,
    body.lux-route-study-card .study-card-semester-table th {
        display: block;
        width: 100%;
    }

    body.lux-route-study-card .study-card-semester-table thead {
        display: none;
    }

    body.lux-route-study-card .study-card-term-row td {
        border-radius: 0;
        border-left: 1px solid var(--lux-soft-chrome-border-accent, var(--lux-border));
        border-right: 1px solid var(--lux-soft-chrome-border-accent, var(--lux-border));
    }

    body.lux-route-study-card .study-card-term-row td:first-child {
        border-radius: 18px 18px 0 0;
    }

    body.lux-route-study-card .study-card-term-row td:last-child {
        border-radius: 0 0 18px 18px;
        text-align: left;
    }

    body.lux-route-study-card .study-card-assessment-window__header {
        flex-direction: column;
    }
}

